@pytest.mark.parametrize("empty_columns", [[], [False, False], lambda X: []])
@pytest.mark.parametrize("empty_position", [0, 1, 2])
def test_column_transformer_empty_columns_pandas_output(
    empty_transformer, empty_columns, empty_position
):
    """Empty selections must not misalign outputs and transformer names."""
    pd = pytest.importorskip("pandas")
    X = pd.DataFrame({"a": [1.0, 3.0], "b": [2.0, 4.0]}, index=[10, 20])
    transformers = [
        ("scaled", StandardScaler(), ["a"]),
        ("kept", "passthrough", ["b"]),
    ]
    transformers.insert(empty_position, ("empty", empty_transformer, empty_columns))
    ct = ColumnTransformer(transformers).set_output(transform="pandas")
    expected = pd.DataFrame(
        {"scaled__a": [-1.0, 1.0], "kept__b": [2.0, 4.0]}, index=X.index
    )

    pd.testing.assert_frame_equal(ct.fit_transform(X), expected)
    pd.testing.assert_frame_equal(ct.transform(X), expected)
    pd.testing.assert_frame_equal(ct.fit(X).transform(X), expected)
    assert_array_equal(ct.get_feature_names_out(), expected.columns)
    assert ct.output_indices_["empty"] == slice(0, 0)
    assert ct.output_indices_["scaled"] == slice(0, 1)
    assert ct.output_indices_["kept"] == slice(1, 2)


